adcs_bdot_state_t filter_trial;
adcs_vec3_t field_rate_local = {0.0, 0.0, 0.0};
adcs_vec3_t field_local;
adcs_actuator_command_t cmd_local;
double mag;
double rate_norm = 0.0;
double gain_used = 0.0;
double slew_limit;
int accepted = 1;
int config_bad = 0;
adcs_status_t st;

/* Reset all output defaults (every cycle) */
dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
dt_output.rate_norm_t_s = 0.0;
dt_output.field_magnitude_t = 0.0;
dt_output.saturation_mask = 0U;
dt_output.slew_mask = 0U;
dt_output.filter_primed_this_cycle = 0;

/* Disable clears all state */
if (dt_input.enable == 0) {
    dt_state.mode = DT_OFF;
    dt_state.good = 0U;
    dt_state.bad = 0U;
    dt_state.filter = (adcs_bdot_state_t){0};
    dt_state.filtered_rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    return;
}

/* Validate configuration and binary flags */
config_bad = 0;
if (dt_input.valid != 0 && dt_input.valid != 1)
    config_bad = 1;
if (!(dt_config.filter_alpha >= 0.0 && dt_config.filter_alpha <= 1.0))
    config_bad = 1;
if (!(dt_config.coarse_gain_a_m2_s_t >= 0.0))
    config_bad = 1;
if (!(dt_config.fine_gain_a_m2_s_t >= 0.0))
    config_bad = 1;
if (!(dt_config.max_dipole_a_m2 > 0.0))
    config_bad = 1;
if (!(dt_config.max_dipole_slew_a_m2_per_cycle > 0.0))
    config_bad = 1;
if (!(dt_config.minimum_field_t > 0.0))
    config_bad = 1;
if (!(dt_config.maximum_field_t > 0.0))
    config_bad = 1;
if (!(dt_config.max_sample_gap_s > 0.0))
    config_bad = 1;
if (!(dt_config.required_good >= 1U && dt_config.required_good <= 20U))
    config_bad = 1;
if (!(dt_config.max_bad >= 1U && dt_config.max_bad <= 20U))
    config_bad = 1;
if (!(dt_config.stop_rate_t_s < dt_config.restart_rate_t_s &&
      dt_config.restart_rate_t_s <= dt_config.fine_enter_rate_t_s &&
      dt_config.fine_enter_rate_t_s < dt_config.fine_exit_rate_t_s))
    config_bad = 1;
if (dt_input.valid == 0)
    config_bad = 1;

/* Determine acceptance */
if (!config_bad) {
    field_local = *dt_input.field_body_t;
    mag = adcs_vec3_norm(&field_local);
    dt_output.field_magnitude_t = mag;
    if (!isfinite(mag) || mag < dt_config.minimum_field_t ||
        mag > dt_config.maximum_field_t) {
        accepted = 0;
    }
} else {
    accepted = 0;
}

/* Prime / re-prime handling */
if (accepted) {
    int need_reprime = 0;
    if (!dt_state.filter.initialized) {
        need_reprime = 1;
    } else {
        double dt_gap = dt_input.time_s - dt_state.filter.previous_time_s;
        if (!isfinite(dt_gap) || dt_gap > dt_config.max_sample_gap_s)
            need_reprime = 1;
    }
    if (need_reprime) {
        dt_state.filter.initialized = 0;
        filter_trial = dt_state.filter;
        st = adcs_bdot_update(&filter_trial, &field_local, dt_input.time_s,
                              dt_config.filter_alpha, &field_rate_local);
        if (st != ADCS_OK) {
            accepted = 0;
        } else {
            dt_state.filter = filter_trial;
            dt_state.mode = DT_COARSE;
            dt_state.good = 0U;
            dt_state.bad = 0U;
            dt_state.filtered_rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            dt_output.filter_primed_this_cycle = 1;
            dt_output.mode = dt_state.mode;
            dt_output.good = dt_state.good;
            dt_output.bad = dt_state.bad;
            dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            dt_output.rate_norm_t_s = 0.0;
            return;
        }
    } else {
        filter_trial = dt_state.filter;
        st = adcs_bdot_update(&filter_trial, &field_local, dt_input.time_s,
                              dt_config.filter_alpha, &field_rate_local);
        if (st != ADCS_OK) {
            accepted = 0;
        } else {
            dt_state.filter = filter_trial;
        }
    }
}

/* Rejected path */
if (!accepted) {
    dt_state.good = 0U;
    if (dt_state.bad < 0xFFFFFFFFU)
        dt_state.bad++;
    if (dt_state.bad >= dt_config.max_bad)
        dt_state.mode = DT_FAULT;
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.rate_norm_t_s = 0.0;
    return;
}

/* Store filtered rate */
dt_state.filtered_rate_t_s = field_rate_local;
rate_norm = adcs_vec3_norm(&field_rate_local);
dt_output.rate_t_s = field_rate_local;
dt_output.rate_norm_t_s = rate_norm;

/* Mode state machine */
if (dt_state.mode == DT_COARSE) {
    if (rate_norm <= dt_config.stop_rate_t_s) {
        if (dt_state.good < 0xFFFFFFFFU)
            dt_state.good++;
        if (dt_state.good >= dt_config.required_good) {
            dt_state.mode = DT_COMPLETE;
            dt_state.good = 0U;
        }
    } else {
        dt_state.good = 0U;
    }
    if (dt_state.mode == DT_COARSE &&
        rate_norm <= dt_config.fine_enter_rate_t_s) {
        dt_state.mode = DT_FINE;
        dt_state.good = 0U;
    }
} else if (dt_state.mode == DT_FINE) {
    if (rate_norm <= dt_config.stop_rate_t_s) {
        if (dt_state.good < 0xFFFFFFFFU)
            dt_state.good++;
        if (dt_state.good >= dt_config.required_good) {
            dt_state.mode = DT_COMPLETE;
            dt_state.good = 0U;
        }
    } else {
        dt_state.good = 0U;
    }
    if (dt_state.mode == DT_FINE &&
        rate_norm >= dt_config.fine_exit_rate_t_s) {
        dt_state.mode = DT_COARSE;
        dt_state.good = 0U;
    }
} else if (dt_state.mode == DT_COMPLETE) {
    if (rate_norm >= dt_config.fine_exit_rate_t_s) {
        dt_state.mode = DT_COARSE;
        dt_state.good = 0U;
    } else if (rate_norm >= dt_config.restart_rate_t_s) {
        dt_state.mode = DT_FINE;
        dt_state.good = 0U;
    }
} else if (dt_state.mode == DT_FAULT) {
    /* stay FAULT */
} else {
    dt_state.mode = DT_COARSE;
}

/* COMPLETE (or FAULT) publish zero dipole */
if (dt_state.mode == DT_COMPLETE || dt_state.mode == DT_FAULT) {
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.rate_t_s = field_rate_local;
    dt_output.rate_norm_t_s = rate_norm;
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    return;
}

/* Gain by mode */
if (dt_state.mode == DT_COARSE)
    gain_used = dt_config.coarse_gain_a_m2_s_t;
else
    gain_used = dt_config.fine_gain_a_m2_s_t;

/* Generate dipole */
st = adcs_bdot_dipole(&field_local, &field_rate_local, gain_used,
                      dt_config.max_dipole_a_m2, &cmd_local);
if (st != ADCS_OK) {
    dt_state.good = 0U;
    if (dt_state.bad < 0xFFFFFFFFU)
        dt_state.bad++;
    if (dt_state.bad >= dt_config.max_bad)
        dt_state.mode = DT_FAULT;
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

dt_output.saturation_mask = cmd_local.saturated_axes;

/* Slew limiting per-component */
slew_limit = dt_config.max_dipole_slew_a_m2_per_cycle;
{
    adcs_vec3_t prev = dt_state.previous_dipole_a_m2;
    adcs_vec3_t out;
    unint32 slew_mask = 0U;
    double d;
    d = cmd_local.command.x - prev.x;
    if (d > slew_limit) {
        out.x = prev.x + slew_limit;
        slew_mask |= 1U;
    } else if (d < -slew_limit) {
        out.x = prev.x - slew_limit;
        slew_mask |= 1U;
    } else {
        out.x = cmd_local.command.x;
    }
    d = cmd_local.command.y - prev.y;
    if (d > slew_limit) {
        out.y = prev.y + slew_limit;
        slew_mask |= 2U;
    } else if (d < -slew_limit) {
        out.y = prev.y - slew_limit;
        slew_mask |= 2U;
    } else {
        out.y = cmd_local.command.y;
    }
    d = cmd_local.command.z - prev.z;
    if (d > slew_limit) {
        out.z = prev.z + slew_limit;
        slew_mask |= 4U;
    } else if (d < -slew_limit) {
        out.z = prev.z - slew_limit;
        slew_mask |= 4U;
    } else {
        out.z = cmd_local.command.z;
    }
    dt_output.slew_mask = slew_mask;
    dt_state.previous_dipole_a_m2 = out;
    dt_output.dipole_a_m2 = out;
}

dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;
return;

